<?php foreach($leads as $l):?><?php $isGoogle=!empty($l['google_place_id']);$phoneRaw=preg_replace('/[^0-9+]/','',$l['phone']??'');$waPhone=preg_replace('/\D/','',$phoneRaw);if(strlen($waPhone)===10)$waPhone='91'.$waPhone;$waMsg=rawurlencode('Hi '.$l['business_name'].', this is '.$_SESSION['name'].' from SetMyWed. We help wedding vendors get more enquiries and bookings. Would you like to know more?');?><div class="card lead" data-lead-id="<?=$l['id']?>"><div class="head"><div><div class="name" id="name-<?=$l['id']?>"><?=h($isGoogle?'Google vendor lead':$l['business_name'])?></div><div class="muted"><?=h($l['category'])?> · <?=h($l['city'])?> · <?=h($l['assigned_name'])?> · Added <?=h(date('d M Y, h:i A',strtotime($l['created_at'])))?></div></div><span class="pill">Score <?=h($l['lead_score'])?></span></div><div class="links"><span class="pill" id="contact-<?=$l['id']?>"><?=!empty($l['contacted_at'])?'✅ Contacted':'📞 Yet to Contact'?></span><?php if($isGoogle):?><button class="iconlink" type="button" onclick="loadGoogleDetails(<?=$l['id']?>,this)">👤 Get vendor details</button><a class="iconlink" id="maps-<?=$l['id']?>" href="<?=h($l['source_url'])?>" target="_blank" rel="noopener">📍 Maps</a><span id="phone-<?=$l['id']?>"></span><span id="website-<?=$l['id']?>"></span><?php else:?><?php if($l['phone']):?><a class="iconlink" href="tel:<?=h($l['phone'])?>">📞 <?=h($l['phone'])?></a><?php endif;?><?php if($l['instagram']):?><a class="iconlink" href="<?=h($l['instagram'])?>" target="_blank" rel="noopener">📸 Instagram</a><?php endif;?><?php if($l['website']):?><a class="iconlink" href="<?=h($l['website'])?>" target="_blank" rel="noopener">🌐 Website</a><?php endif;?><?php endif;?><span class="pill"><?=h($l['status'])?></span></div><div class="actions"><form method="post" style="display:inline"><input type="hidden" name="action" value="toggle_star"><input type="hidden" name="id" value="<?=$l['id']?>"><input type="hidden" name="starred" value="<?=!empty($l['starred'])?0:1?>"><button type="submit"><?=!empty($l['starred'])?'⭐ Starred':'☆ Star'?></button></form><?php if($isGoogle):?><button class="call" type="button" onclick="loadGoogleDetails(<?=$l['id']?>,this,true)">📞 Call</button><button class="wa" type="button" onclick="loadGoogleDetails(<?=$l['id']?>,this,false).then(()=>openWA(<?=$l['id']?>))">💬 WhatsApp</button><?php else:?><a class="call" href="tel:<?=h($l['phone'])?>" onclick="markContacted(<?=$l['id']?>)">📞 Call</a><?php if($waPhone):?><a class="wa" href="https://wa.me/<?=h($waPhone)?>?text=<?=$waMsg?>" target="_blank" rel="noopener">💬 WhatsApp</a><?php endif;?><?php endif;?><form method="post"><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=$l['id']?>"><select name="status"><option>New</option><option>Follow-up</option><option>Interested</option><option>Not Interested</option><option>Converted</option><option>Wrong Number</option><option>DNC</option></select><button>Save status</button></form></div><details style="margin-top:12px"><summary>📝 Remark / Follow-up</summary><form method="post" style="margin-top:10px"><input type="hidden" name="action" value="remark"><input type="hidden" name="id" value="<?=$l['id']?>"><textarea name="remark" rows="2" style="width:100%;box-sizing:border-box" placeholder="What happened on the call?"><?=h($l['remark'])?></textarea><button class="btn" style="margin-top:6px">Save remark</button></form><form method="post" style="margin-top:8px"><input type="hidden" name="action" value="followup"><input type="hidden" name="id" value="<?=$l['id']?>"><input type="datetime-local" name="next" value="<?=h($l['next_followup'])?>" required><button class="btn primary">Schedule follow-up</button></form><?php if($view==='followups'&&($l['status']==='Follow-up'||$l['next_followup'])):?><form method="post" style="margin-top:8px" onsubmit="return confirm('Remove this lead from Follow-ups?')"><input type="hidden" name="action" value="remove_lead_followup"><input type="hidden" name="id" value="<?=$l['id']?>"><button class="btn" type="submit">🗑️ Remove from Follow-ups</button></form><?php endif;?></details><?php if($l['next_followup']):?><div class="muted" style="margin-top:8px">⏰ Next call: <?=h($l['next_followup'])?></div><?php endif;?></div><?php endforeach;?></div><?php endif;?><?php endif;?></div></div><script>
const googleCache={};
function markContacted(id){
 const el=document.getElementById('contact-'+id);if(el){el.textContent='✅ Contacted';}
 try{fetch('/',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'action=contact&id='+encodeURIComponent(id),credentials:'same-origin',keepalive:true}).catch(()=>{});}catch(e){}
}
async function loadGoogleDetails(id,button,callNow=false){if(googleCache[id]){if(callNow&&googleCache[id].phone)location.href='tel:'+googleCache[id].phone;return googleCache[id];}button.disabled=true;const old=button.textContent;button.textContent='Loading...';try{const r=await fetch('google_details.php?id='+encodeURIComponent(id),{credentials:'same-origin'});const j=await r.json();if(!r.ok)throw new Error(j.error||'Unable to load details');googleCache[id]=j;document.getElementById('name-'+id).textContent=j.name||'Google vendor';const phone=document.getElementById('phone-'+id);phone.innerHTML=j.phone?'<a class="iconlink" href="tel:'+escapeAttr(j.phone)+'">📞 '+escapeHtml(j.phone)+'</a>':'<span class="muted">No phone listed</span>';if(j.website)document.getElementById('website-'+id).innerHTML='<a class="iconlink" href="'+escapeAttr(j.website)+'" target="_blank" rel="noopener">🌐 Website</a>';if(j.maps)document.getElementById('maps-'+id).href=j.maps;if(callNow&&j.phone){markContacted(id);location.href='tel:'+j.phone;}button.textContent='✓ Details loaded';return j;}catch(e){alert(e.message);button.textContent=old;return null;}finally{button.disabled=false;}}
function openWA(id){const j=googleCache[id];if(!j||!j.phone){alert('No mobile number available for WhatsApp.');return;}let p=String(j.phone).replace(/\D/g,'');if(p.length===10)p='91'+p;let msg=encodeURIComponent('Hi '+(j.name||'there')+', this is '+<?=json_encode($_SESSION['name'])?>+' from SetMyWed. We help wedding vendors get more enquiries and bookings. Would you like to know more?');window.open('https://wa.me/'+p+'?text='+msg,'_blank');}
function escapeHtml(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));}function escapeAttr(v){return escapeHtml(v);}
const quotes=["Success is the sum of small efforts, repeated day in and day out.","Every call is an opportunity.","Focus on the next conversation, not the last rejection.","Small progress every day creates big results.","Consistency turns targets into achievements.","One good conversation can change the whole day.","Discipline today creates freedom tomorrow."];const q=document.getElementById("quote");if(q)q.textContent=quotes[new Date().getDate()%quotes.length];
document.querySelectorAll(".lead[data-lead-id]").forEach(card=>{const btn=card.querySelector("button[onclick^='loadGoogleDetails']");if(btn){loadGoogleDetails(card.dataset.leadId,btn,false);}});
if("serviceWorker" in navigator)navigator.serviceWorker.register("/sw.js").catch(()=>{});</script></body></html>
